(function(){
  var $=function(id){return document.getElementById(id)};
  var money=function(n){return n.toLocaleString(undefined,{maximumFractionDigits:0})};
  function calc(){
    var P=+$('p').value||0, rate=+$('r').value||0, years=+$('y').value||0;
    var n=+$('n').value||12, add=+$('c').value||0, atStart=$('when').value==='start';
    if(years<=0){ $('note').textContent='Enter at least one year.'; return; }
    // Stepped month by month rather than closed form, because the deposit is
    // monthly while compounding may not be. Interest is credited only on the
    // months where a compounding period actually ends.
    var months=Math.round(years*12);
    var periodEvery = 12/n;            // months between compounding events
    var ratePerPeriod = rate/100/n;
    var bal=P, contributed=P, rows=[], acc=0;
    for(var m=1;m<=months;m++){
      if(atStart){ bal+=add; contributed+=add; }
      acc+=1;
      if(acc>=periodEvery){ bal*=1+ratePerPeriod*(acc/periodEvery); acc=0; }
      if(!atStart){ bal+=add; contributed+=add; }
      if(m%12===0 && (years<=10 || (m/12)%5===0 || m===months)){
        rows.push([(m/12)+' year'+(m/12>1?'s':''), bal, bal-contributed]);
      }
    }
    $('final').textContent=money(bal);
    $('paid').textContent=money(contributed);
    $('earned').textContent=money(bal-contributed);
    var html='<div class="hd"><span>After</span><span>Balance</span></div>';
    html+=rows.map(function(x){return '<div><span>'+x[0]+'</span><b>'+money(x[1])+'</b></div>'}).join('');
    $('brk').innerHTML=html;
    var share = bal>0 ? (bal-contributed)/bal*100 : 0;
    $('note').textContent='Interest makes up '+share.toFixed(0)+
      '% of the final balance. The longer the money stays invested, the larger that share becomes.';
    if(window.WT) WT.resize();
  }
  ['p','r','y','n','c','when'].forEach(function(id){
    $(id).addEventListener('input',calc); $(id).addEventListener('change',calc);
  });
  $('go').addEventListener('click',calc);
  $('copy').addEventListener('click',function(){
    var ok=WT.copy('Final balance: '+$('final').textContent+', of which '+$('earned').textContent+' is interest.');
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  calc();
})();
